use std::sync::{Arc, Mutex};

struct Account { balance: i64 }

let account = Arc::new(Mutex::new(Account { balance: 0 }));
let handle = Arc::clone(&account);            // the published lock travels
std::thread::spawn(move || {
    let mut guard = handle.lock().unwrap();   // guard = lock + access right
    guard.balance += 5;
});                                           // released when guard drops
// second object, second lock: always acquire in the same documented order
